def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen, comps = set(), []

    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == col:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            rs = [y for y,x in cells]
            cs = [x for y,x in cells]
            comps.append((col, cells, min(rs), max(rs), min(cs), max(cs)))

    def l_info(obj):
        _, cells, r0, r1, c0, c1 = obj
        if r1 == r0 or c1 == c0:
            return None
        shapes = [
            {(r0,c) for c in range(c0,c1+1)} | {(r,c0) for r in range(r0,r1+1)},
            {(r0,c) for c in range(c0,c1+1)} | {(r,c1) for r in range(r0,r1+1)},
            {(r1,c) for c in range(c0,c1+1)} | {(r,c0) for r in range(r0,r1+1)},
            {(r1,c) for c in range(c0,c1+1)} | {(r,c1) for r in range(r0,r1+1)}
        ]
        for i, shape in enumerate(shapes):
            if cells == shape:
                return i
        return None

    cues = [o for o in comps if l_info(o) is not None]
    if not cues:
        return [row[:] for row in grid]
    cue = max(cues, key=lambda o: len(o[1]))
    cue_col, cue_cells, r0, r1, c0, c1 = cue
    ch, cw = r1-r0+1, c1-c0+1

    candidates = []
    for col, cells, a, b, d, e in comps:
        if col == cue_col:
            continue
        oh, ow = b-a+1, e-d+1
        dim_error = min(
            abs(oh-ch/2) + abs(ow-cw/2),
            abs(oh-cw/2) + abs(ow-ch/2)
        )
        area_error = abs(len(cells) - len(cue_cells)/2)
        candidates.append((dim_error + 0.15*area_error, dim_error, cells))

    if not candidates:
        return [row[:] for row in grid]
    target = min(candidates, key=lambda x: (x[0], x[1]))[2]
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = cue_col
    return out
